616				t.Errorf("Test %d: Expected %d server blocks, got %d",
617					i, len(test.keys), len(blocks))
618				continue
619			}
620			for j, block := range blocks {
621				if len(block.Keys) != len(test.keys[j]) {
622					t.Errorf("Test %d: Expected %d keys in block %d, got %d: %v",
623						i, len(test.keys[j]), j, len(block.Keys), block.Keys)
624					continue
625				}
626				for k, addr := range block.GetKeysText() {
627					if addr != test.keys[j][k] {
628						t.Errorf("Test %d, block %d, key %d: Expected '%s', but got '%s'",
629							i, j, k, test.keys[j][k], addr)
