636	func TestEnvironmentReplacement(t *testing.T) {
637		os.Setenv("FOOBAR", "foobar")
638		os.Setenv("CHAINED", "$FOOBAR")
639	
640		for i, test := range []struct {
641			input  string
642			expect string
643		}{
644			{
645				input:  "",
646				expect: "",
647			},
648			{
649				input:  "foo",
650				expect: "foo",
651			},
652			{
653				input:  "{$NOT_SET}",
654				expect: "",
655			},
656			{
657				input:  "foo{$NOT_SET}bar",
658				expect: "foobar",
659			},
660			{
661				input:  "{$FOOBAR}",
662				expect: "foobar",
663			},
664			{
665				input:  "foo {$FOOBAR} bar",
666				expect: "foo foobar bar",
667			},
668			{
669				input:  "foo{$FOOBAR}bar",
670				expect: "foofoobarbar",
671			},
672			{
673				input:  "foo\n{$FOOBAR}\nbar",
674				expect: "foo\nfoobar\nbar",
675			},
676			{
677				input:  "{$FOOBAR} {$FOOBAR}",
678				expect: "foobar foobar",
679			},
680			{
681				input:  "{$FOOBAR}{$FOOBAR}",
682				expect: "foobarfoobar",
683			},
684			{
685				input:  "{$CHAINED}",
686				expect: "$FOOBAR", // should not chain env expands
687			},
688			{
689				input:  "{$FOO:default}",
690				expect: "default",
691			},
692			{
693				input:  "foo{$BAR:bar}baz",
694				expect: "foobarbaz",
695			},
696			{
697				input:  "foo{$BAR:$FOOBAR}baz",
698				expect: "foo$FOOBARbaz", // should not chain env expands
699			},
700			{
701				input:  "{$FOOBAR",
702				expect: "{$FOOBAR",
703			},
704			{
705				input:  "{$LONGER_NAME $FOOBAR}",
706				expect: "",
707			},
708			{
709				input:  "{$}",
710				expect: "{$}",
711			},
712			{
713				input:  "{$$}",
714				expect: "",
715			},
716			{
717				input:  "{$",
718				expect: "{$",
719			},
720			{
721				input:  "}{$",
722				expect: "}{$",
723			},
724		} {
725			actual := replaceEnvVars([]byte(test.input))
726			if !bytes.Equal(actual, []byte(test.expect)) {
727				t.Errorf("Test %d: Expected: '%s' but got '%s'", i, test.expect, actual)
728			}
729		}
730	}
