package caddyfile

import (
	"fmt"
	"slices"
	"strings"
)

type adjacency map[string][]string

type importGraph struct {
	nodes map[string]struct{}
	edges adjacency
}

func (i *importGraph) addNode(name string) {
	if i.nodes == nil {
		i.nodes = make(map[string]struct{})
	}
	if _, exists := i.nodes[name]; exists {
		return
	}
	i.nodes[name] = struct{}{}
}

func (i *importGraph) addNodes(names []string) {
	for _, name := range names {
		i.addNode(name)
	}
}

func (i *importGraph) removeNode(name string) {
	delete(i.nodes, name)
}

func (i *importGraph) removeNodes(names []string) {
	for _, name := range names {
		i.removeNode(name)
	}
}

func (i *importGraph) addEdge(from, to string) error {
	if !i.exists(from) || !i.exists(to) {
		return fmt.Errorf("one of the nodes does not exist")
	}

	if i.areConnected(from, to) {
		// if connected, there's nothing to do
		return nil
	}

	// adding the edge from -> to closes a cycle if `to` can
	// already reach `from` (including the self-edge case);
	// findPath returns the readable chain to -> ... -> from
	if path := i.findPath(to, from); path != nil {
		cycle := append(path, to)
		return fmt.Errorf("a cycle of imports exists between %s and %s: %s",
			from, to, strings.Join(cycle, " -> "))
	}

	if i.nodes == nil {
		i.nodes = make(map[string]struct{})
	}
	if i.edges == nil {
		i.edges = make(adjacency)
	}

	i.edges[from] = append(i.edges[from], to)
	return nil
}

func (i *importGraph) addEdges(from string, tos []string) error {
	for _, to := range tos {
		err := i.addEdge(from, to)
		if err != nil {
			return err
		}
	}
	return nil
}

func (i *importGraph) areConnected(from, to string) bool {
	al, ok := i.edges[from]
	if !ok {
		return false
	}
	return slices.Contains(al, to)
}

// findPath returns a path of node names from start to target
// following existing edges, or nil if no such path exists.
// Edges leave nodes in insertion order, so the reported cycle
// is stable for identical inputs.
func (i *importGraph) findPath(start, target string) []string {
	if start == target {
		return []string{start}
	}
	visited := map[string]bool{start: true}
	queue := [][]string{{start}}
	for len(queue) > 0 {
		path := queue[0]
		queue = queue[1:]
		current := path[len(path)-1]
		for _, next := range i.edges[current] {
			if next == target {
				return append(path, next)
			}
			if !visited[next] {
				visited[next] = true
				queue = append(queue, append(append([]string{}, path...), next))
			}
		}
	}
	return nil
}

func (i *importGraph) exists(key string) bool {
	_, exists := i.nodes[key]
	return exists
}

