// Files returns a deep copy of the tree's files keyed by cleaned
// path. Parse uses it to freeze the whole tree up front, so callers
// may keep mutating the source map without affecting any parse.
func (r *MapImportReader) Files() map[string][]byte {
	out := make(map[string][]byte, len(r.files))
	for name, contents := range r.files {
		out[name] = []byte(contents)
	}
	return out
}

// Dirs returns the cleaned synthetic directory paths of the tree.
func (r *MapImportReader) Dirs() []string {
	dirs := make([]string, 0, len(r.dirs))
	for d := range r.dirs {
		dirs = append(dirs, d)
	}
	return dirs
}

