package caddyfile

import (
	"errors"
	"io/fs"
	"path/filepath"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
)

// flattenBlocks renders parse results as a deterministic sequence
// of "key" and "segment token bytes" lines for byte-level comparison.
func flattenBlocks(blocks []ServerBlock) string {
	var sb strings.Builder
	for bi, block := range blocks {
		sb.WriteString("block ")
		sb.WriteString(filepath.ToSlash(strings.Join(block.GetKeysText(), ",")))
		sb.WriteByte('\n')
		for _, seg := range block.Segments {
			for ti, tok := range seg {
				if ti > 0 {
					sb.WriteByte(' ')
				}
				sb.WriteString(tok.Text)
			}
			sb.WriteByte('\n')
		}
		if bi < len(blocks)-1 {
			sb.WriteString("---\n")
		}
	}
	return sb.String()
}

func mustParseWithReader(t *testing.T, filename string, files map[string]string) string {
	t.Helper()
	blocks, err := Parse(filename, []byte(files[filename]), WithImportReader(NewMapImportReader(files)))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if blocks == nil {
		t.Fatal("successful parse returned nil blocks")
	}
	return flattenBlocks(blocks)
}

func parseErrWithReader(t *testing.T, filename string, files map[string]string) error {
	t.Helper()
	blocks, err := Parse(filename, []byte(files[filename]), WithImportReader(NewMapImportReader(files)))
	if err == nil {
		t.Fatalf("expected error, got blocks:\n%s", flattenBlocks(blocks))
	}
	if blocks != nil {
		t.Fatalf("failed parse must not return usable blocks, got:\n%s", flattenBlocks(blocks))
	}
	return err
}

func TestParseWithImportReaderRelativeAndGlobOrder(t *testing.T) {
	files := map[string]string{
		"/etc/caddy/Caddyfile": "example.com\nimport sites/*.caddy\n",
		"/etc/caddy/sites/b.caddy": `b.example.com {
	respond B
}
`,
		"/etc/caddy/sites/a.caddy": `a.example.com {
	respond A
}
`,
		"/etc/caddy/sites/sub/c.caddy": "c.example.com {\n\trespond C\n}\n",
	}
	got := mustParseWithReader(t, "/etc/caddy/Caddyfile", files)
	want := strings.Join([]string{
		"block example.com",
		"",
		"---",
		"block a.example.com",
		"respond A",
		"---",
		"block b.example.com",
		"respond B",
		"",
	}, "\n")
	if got != want {
		t.Errorf("glob expansion order mismatch\nwant:\n%s\ngot:\n%s", want, got)
	}
}

func TestParseWithImportReaderDotSegmentsCleaned(t *testing.T) {
	files := map[string]string{
		"/etc/caddy/Caddyfile":     "example.com\nimport ./sub/../sites/a.caddy\n",
		"/etc/caddy/sites/a.caddy": "a.example.com\nrespond A\n",
	}
	got := mustParseWithReader(t, "/etc/caddy/Caddyfile", files)
	if !strings.Contains(got, "block a.example.com") {
		t.Errorf("relative import with dot segments failed:\n%s", got)
	}
}

func TestParseImportErrorsAreFailures(t *testing.T) {
	// unreadable target of a non-glob import
	files := map[string]string{
		"/Caddyfile": "example.com\nimport missing.caddy\n",
	}
	err := parseErrWithReader(t, "/Caddyfile", files)
	if !strings.Contains(err.Error(), "file to import not found") {
		t.Errorf("expected not-found error, got: %v", err)
	}
	if strings.Contains(err.Error(), "..") {
		t.Errorf("error path must be cleaned: %v", err)
	}

	// unterminated quote in imported file
	files = map[string]string{
		"/Caddyfile":    "example.com\nimport bad.caddy\n",
		"/bad.caddy":    `respond "unclosed`,
	}
	if err := parseErrWithReader(t, "/Caddyfile", files); !strings.Contains(err.Error(), "/Caddyfile:1") {
		t.Errorf("error must point at the import statement, got: %v", err)
	}

	// directory target
	dirFiles := map[string]string{"/Caddyfile": "import /etc\n"}
	r := NewMapImportReader(dirFiles) // add a synthetic directory
	r2 := r.Snapshot().(*MapImportReader)
	r2.dirs["/etc"] = struct{}{}
	blocks, err := Parse("/Caddyfile", []byte(dirFiles["/Caddyfile"]), WithImportReader(r2))
	if err == nil {
		t.Fatalf("expected directory import error, got %v", blocks)
	}
	if !strings.Contains(err.Error(), "is a directory") {
		t.Errorf("expected directory error, got: %v", err)
	}
}

// errorReader fails every ReadFile with a sentinel error.
type errorReader struct{ calls atomic.Int32 }

func (r *errorReader) ReadFile(string) ([]byte, error) {
	r.calls.Add(1)
	return nil, errors.New("disk on fire")
}
func (r *errorReader) Stat(string) (fs.FileInfo, error) {
	return nil, &fs.PathError{Op: "stat", Path: "x", Err: fs.ErrNotExist}
}
func (r *errorReader) Glob(string) ([]string, error) { return nil, nil }

func TestParseImportReadError(t *testing.T) {
	r := &errorReader{}
	blocks, err := Parse("/Caddyfile", []byte("import /a.caddy\n"), WithImportReader(r))
	if err == nil {
		t.Fatalf("expected read error, got %v", blocks)
	}
	if !strings.Contains(err.Error(), "disk on fire") {
		t.Errorf("expected wrapped read error, got: %v", err)
	}
}

// versionedReader returns a different version on every ReadFile,
// simulating a reader that swaps data between repeated reads.
type versionedReader struct {
	mu       sync.Mutex
	contents map[string]string
	reads    map[string]int
}

func (r *versionedReader) ReadFile(name string) ([]byte, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.reads[name]++
	body := r.contents[name]
	if body == "" {
		return nil, &fs.PathError{Op: "open", Path: name, Err: fs.ErrNotExist}
	}
	return []byte(body + " # read " + itoa(r.reads[name])), nil
}
func (r *versionedReader) Stat(name string) (fs.FileInfo, error) {
	if _, ok := r.contents[name]; !ok {
		return nil, &fs.PathError{Op: "stat", Path: name, Err: fs.ErrNotExist}
	}
	return mapFileInfo{name: filepath.Base(name), size: 1}, nil
}
func (r *versionedReader) Glob(pattern string) ([]string, error) {
	var out []string
	for name := range r.contents {
		matched, err := filepath.Match(pattern, name)
		if err != nil {
			return nil, err
		}
		if matched {
			out = append(out, name)
		}
	}
	sortStrings(out)
	return out, nil
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var b [20]byte
	i := len(b)
	for n > 0 {
		i--
		b[i] = byte('0' + n%10)
		n /= 10
	}
	return string(b[i:])
}

func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j-1] > s[j]; j-- {
			s[j-1], s[j] = s[j], s[j-1]
		}
	}
}

func TestParseSnapshotRepeatedReadsAndDuplicateImports(t *testing.T) {
	// the same file is imported twice; even though each read would
	// return another version, both expansions must come from one read
	r := &versionedReader{
		contents: map[string]string{
			"/Caddyfile": "example.com\nimport shared.caddy\nimport shared.caddy\n",
			"/shared.caddy": `respond "v"`,
		},
		reads: map[string]int{},
	}
	blocks, err := Parse("/Caddyfile", []byte(r.contents["/Caddyfile"]), WithImportReader(r))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	segs := blocks[0].Segments
	if len(segs) != 2 {
		t.Fatalf("expected two respond segments (duplicate import), got %d", len(segs))
	}
	if segs[0][1].Text != segs[1][1].Text {
		t.Errorf("duplicate imports must use one snapshot: %q vs %q", segs[0][1].Text, segs[1][1].Text)
	}
	if r.reads["/shared.caddy"] != 1 {
		t.Errorf("expected exactly one read of shared file, got %d", r.reads["/shared.caddy"])
	}
}

func TestParseSnapshotFixedForCallAndReplaceableAfterwards(t *testing.T) {
	t.Parallel()

	v1 := map[string]string{
		"/Caddyfile": "example.com\nimport inc.caddy\n",
		"/inc.caddy": "respond ONE\n",
	}
	v2 := map[string]string{
		"/Caddyfile": "example.com\nimport inc.caddy\n",
		"/inc.caddy": "respond TWO\n",
	}

	tree := NewMapImportReader(v1)
	blocks, err := Parse("/Caddyfile", []byte(v1["/Caddyfile"]), WithImportReader(tree))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got := blocks[0].Segments[0][1].Text; got != "ONE" {
		t.Fatalf("expected ONE, got %q", got)
	}

	// mutate the source tree after the parse returned; the result
	// must keep its bytes, and a new parse sees only the new tree
	tree = NewMapImportReader(v2)
	blocks2, err := Parse("/Caddyfile", []byte(v2["/Caddyfile"]), WithImportReader(tree))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got := blocks2[0].Segments[0][1].Text; got != "TWO" {
		t.Errorf("new parse must see only new tree, got %q", got)
	}
	if got := blocks[0].Segments[0][1].Text; got != "ONE" {
		t.Errorf("earlier result changed after reader mutation: %q", got)
	}
}

// mutableReader exposes a lock-protected tree that tests mutate
// while a parse is blocked on first read.
type mutableReader struct {
	mu       sync.Mutex
	files    map[string]string
	started  chan struct{}
	proceed  chan struct{}
	proceedOnce sync.Once
}

func (r *mutableReader) lockData() (map[string]string, func()) {
	r.mu.Lock()
	return r.files, r.mu.Unlock
}

func (r *mutableReader) ReadFile(name string) ([]byte, error) {
	closeOnce := func() {
		select {
		case <-r.started:
		default:
			close(r.started)
		}
	}
	if name == "/inc.caddy" {
		closeOnce()
		<-r.proceed
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	body, ok := r.files[name]
	if !ok {
		return nil, &fs.PathError{Op: "open", Path: name, Err: fs.ErrNotExist}
	}
	return []byte(body), nil
}

func (r *mutableReader) Stat(name string) (fs.FileInfo, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	body, ok := r.files[name]
	if !ok {
		return nil, &fs.PathError{Op: "stat", Path: name, Err: fs.ErrNotExist}
	}
	return mapFileInfo{name: filepath.Base(name), size: int64(len(body))}, nil
}

func (r *mutableReader) Glob(pattern string) ([]string, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	var out []string
	for name := range r.files {
		matched, err := filepath.Match(pattern, name)
		if err != nil {
			return nil, err
		}
		if matched {
			out = append(out, name)
		}
	}
	sortStrings(out)
	return out, nil
}

func (r *mutableReader) release() { r.proceedOnce.Do(func() { close(r.proceed) }) }

func TestParseSnapshotImmuneToConcurrentMutation(t *testing.T) {
	t.Parallel()

	r := &mutableReader{
		files: map[string]string{
			"/Caddyfile": "example.com\nimport inc.caddy\n",
			"/inc.caddy": "respond SNAPSHOT\n",
		},
		started: make(chan struct{}),
		proceed: make(chan struct{}),
	}

	type result struct {
		text string
		err  error
	}
	done := make(chan result, 1)
	go func() {
		blocks, err := Parse("/Caddyfile", []byte(r.files["/Caddyfile"]), WithImportReader(r))
		if err != nil {
			done <- result{err: err}
			return
		}
		done <- result{text: blocks[0].Segments[0][1].Text}
	}()

	<-r.started
	// the parse is pinned on its first import read; rewrite the
	// underlying file and only then let it continue
	r.mu.Lock()
	r.files["/inc.caddy"] = "respond MUTATED\n"
	r.mu.Unlock()
	r.release()

	res := <-done
	if res.err != nil {
		t.Fatalf("unexpected error: %v", res.err)
	}
	if res.text != "SNAPSHOT" {
		t.Errorf("parse mixed in another snapshot: got %q, want SNAPSHOT", res.text)
	}
}

func TestParseDeterministicBytesAndErrors(t *testing.T) {
	t.Parallel()

	files := map[string]string{
		"/Caddyfile": "import a.caddy\nimport b.caddy\n",
		"/a.caddy":   "a.example.com\nrespond A\n",
		"/b.caddy":   "b.example.com\nrespond B\n",
	}
	var first string
	for i := 0; i < 3; i++ {
		got := mustParseWithReader(t, "/Caddyfile", files)
		if i == 0 {
			first = got
		} else if got != first {
			t.Errorf("run %d differs:\n%s\nvs\n%s", i, first, got)
		}
	}

	// failure text is stable too
	badFiles := map[string]string{
		"/Caddyfile": "import a.caddy\n",
		"/a.caddy":   "import b.caddy\n",
		"/b.caddy":   "import a.caddy\n",
	}
	var firstErr string
	for i := 0; i < 3; i++ {
		err := parseErrWithReader(t, "/Caddyfile", badFiles)
		if i == 0 {
			firstErr = err.Error()
		} else if err.Error() != firstErr {
			t.Errorf("run %d error differs:\n%s\nvs\n%s", i, firstErr, err.Error())
		}
	}
	if !strings.Contains(firstErr, "/a.caddy -> /b.caddy -> /a.caddy") {
		t.Errorf("cycle error must show readable closed chain, got: %s", firstErr)
	}
}

func TestParseParallelCallsIsolated(t *testing.T) {
	t.Parallel()

	const workers = 32
	var wg sync.WaitGroup
	wg.Add(workers)
	for w := 0; w < workers; w++ {
		i := w
		go func() {
			defer wg.Done()
			want := "respond " + itoa(i)
			files := map[string]string{
				"/Caddyfile": "example.com\nimport inc.caddy\n",
				"/inc.caddy": want + "\n",
			}
			blocks, err := Parse("/Caddyfile", []byte(files["/Caddyfile"]),
				WithImportReader(NewMapImportReader(files)))
			if err != nil {
				t.Errorf("worker %d: %v", i, err)
				return
			}
			if got := blocks[0].Segments[0][1].Text; got != itoa(i) {
				t.Errorf("worker %d got %q, want %q", i, got, want)
			}
		}()
	}
	wg.Wait()
}

func TestParseArgsScopeDoesNotLeakIntoNestedFiles(t *testing.T) {
	// outer passes OUTER; the inner file declares no args, so its
	// {args[0]} must fail rather than see the outer value
	files := map[string]string{
		"/Caddyfile": "import inner.caddy OUTER\n",
		"/inner.caddy": `(s) {
	respond {args[0]}
}
import s
`,
	}
	parseErrWithReader(t, "/Caddyfile", files)

	// but a nested import with its own args uses those
	files = map[string]string{
		"/Caddyfile": "import inner.caddy OUTER\n",
		"/inner.caddy": "example.com\nimport leaf.caddy INNER\n",
		"/leaf.caddy":  "respond {args[0]}\n",
	}
	got := mustParseWithReader(t, "/Caddyfile", files)
	if !strings.Contains(got, "respond INNER") {
		t.Errorf("nested import must use its own args:\n%s", got)
	}
}

func TestParseArgsSnippetScope(t *testing.T) {
	// args passed to snippet A are not visible inside snippet B
	files := map[string]string{
		"/Caddyfile": `(A) {
	import B
}
(B) {
	respond {args[0]}
}
import A VALUE
`,
	}
	parseErrWithReader(t, "/Caddyfile", files)

	// args passed directly to B work
	files["/Caddyfile"] = `(A) {
	import B DIRECT
}
(B) {
	respond {args[0]}
}
import A
`
	got := mustParseWithReader(t, "/Caddyfile", files)
	if !strings.Contains(got, "respond DIRECT") {
		t.Errorf("direct snippet args should expand:\n%s", got)
	}
}

func TestParseArgsStrictnessEndToEnd(t *testing.T) {
	// undeclared placeholder fails the whole parse
	files := map[string]string{
		"/Caddyfile": "example.com\nimport inc.caddy\n",
		"/inc.caddy": "respond {args[0]}\n",
	}
	parseErrWithReader(t, "/Caddyfile", files)

	// out-of-range placeholder fails the parse
	files["/Caddyfile"] = "example.com\nimport inc.caddy only\n"
	parseErrWithReader(t, "/Caddyfile", files)

	// variadic expansion: spaces, quotes, and empty values stay as
	// separate tokens in declaration order
	files = map[string]string{
		"/Caddyfile": "example.com\nimport inc.caddy a \"b c\" \"\" d\n",
		"/inc.caddy":  "respond {args[:]}\n",
	}
	blocks, err := Parse("/Caddyfile", []byte(files["/Caddyfile"]), WithImportReader(NewMapImportReader(files)))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	seg := blocks[0].Segments[0]
	want := []string{"respond", "a", "b c", "", "d"}
	if len(seg) != len(want) {
		t.Fatalf("expected %d tokens, got %v", len(want), seg)
	}
	for i, tok := range seg {
		if tok.Text != want[i] {
			t.Errorf("token %d: got %q want %q", i, tok.Text, want[i])
		}
	}

	// braces inside arg values are never expanded again
	files = map[string]string{
		"/Caddyfile": "example.com\nimport inc.caddy '{host}'\n",
		"/inc.caddy":  "respond {args[0]}\n",
	}
	got := mustParseWithReader(t, "/Caddyfile", files)
	if !strings.Contains(got, "respond {host}") {
		t.Errorf("braces in arg value must survive verbatim:\n%s", got)
	}
}

func TestParseNoMatchGlobStillSucceeds(t *testing.T) {
	files := map[string]string{
		"/Caddyfile": "example.com\nimport empty/*.caddy\nrespond ok\n",
	}
	got := mustParseWithReader(t, "/Caddyfile", files)
	if !strings.Contains(got, "respond ok") {
		t.Errorf("glob without matches must keep success semantics:\n%s", got)
	}
}

func TestParseSnippetAndSiteOrderPreserved(t *testing.T) {
	files := map[string]string{
		"/Caddyfile": `(common) {
	header X-Common yes
}
a.example.com {
	import common
	respond A
}
b.example.com {
	respond B
}
`,
	}
	got := mustParseWithReader(t, "/Caddyfile", files)
	want := "block a.example.com\nheader X-Common yes\nrespond A\n---\nblock b.example.com\nrespond B\n"
	if got != want {
		t.Errorf("order mismatch\nwant:\n%s\ngot:\n%s", want, got)
