		t.Errorf("relative import with dot segments failed:\n%s", got)
	}
}

func TestParseImportErrorsAreFailures(t *testing.T) {
	// unreadable target of a non-glob import
	files := map[string]string{
		"/Caddyfile": "example.com\nimport missing.caddy\n",
	}
	err := parseErrWithReader(t, "/Caddyfile", files)
	if !strings.Contains(err.Error(), "file to import not found") {
		t.Errorf("expected not-found error, got: %v", err)
	}
	if strings.Contains(err.Error(), "..") {
		t.Errorf("error path must be cleaned: %v", err)
	}

	// unterminated quote in imported file
	files = map[string]string{
		"/Caddyfile":    "example.com\nimport bad.caddy\n",
		"/bad.caddy":    `respond "unclosed`,
	}
	if err := parseErrWithReader(t, "/Caddyfile", files); !strings.Contains(err.Error(), "/Caddyfile:1") {
		t.Errorf("error must point at the import statement, got: %v", err)
	}

	// directory target
	dirFiles := map[string]string{"/Caddyfile": "import /etc\n"}
	r := NewMapImportReader(dirFiles) // add a synthetic directory
	r2 := r.Snapshot().(*MapImportReader)
	r2.dirs["/etc"] = struct{}{}
	blocks, err := Parse("/Caddyfile", []byte(dirFiles["/Caddyfile"]), WithImportReader(r2))
	if err == nil {
		t.Fatalf("expected directory import error, got %v", blocks)
	}
	if !strings.Contains(err.Error(), "is a directory") {
		t.Errorf("expected directory error, got: %v", err)
