// mutableReader exposes a lock-protected tree that tests mutate
// while a parse is blocked on first read.
type mutableReader struct {
	mu       sync.Mutex
	files    map[string]string
	started  chan struct{}
	proceed  chan struct{}
	proceedOnce sync.Once
}

func (r *mutableReader) lockData() (map[string]string, func()) {
	r.mu.Lock()
	return r.files, r.mu.Unlock
}

func (r *mutableReader) ReadFile(name string) ([]byte, error) {
	closeOnce := func() {
		select {
		case <-r.started:
		default:
			close(r.started)
		}
	}
	if name == "/inc.caddy" {
		closeOnce()
		<-r.proceed
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	body, ok := r.files[name]
	if !ok {
		return nil, &fs.PathError{Op: "open", Path: name, Err: fs.ErrNotExist}
	}
	return []byte(body), nil
}

func (r *mutableReader) Stat(name string) (fs.FileInfo, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	body, ok := r.files[name]
	if !ok {
		return nil, &fs.PathError{Op: "stat", Path: name, Err: fs.ErrNotExist}
	}
	return mapFileInfo{name: filepath.Base(name), size: int64(len(body))}, nil
}

func (r *mutableReader) Glob(pattern string) ([]string, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	var out []string
	for name := range r.files {
		matched, err := filepath.Match(pattern, name)
		if err != nil {
			return nil, err
		}
		if matched {
			out = append(out, name)
		}
	}
	sortStrings(out)
	return out, nil
}

func (r *mutableReader) release() { r.proceedOnce.Do(func() { close(r.proceed) }) }

