15	package caddyfile
16	
17	import (
18		"errors"
19		"io/fs"
20		"path/filepath"
21		"strings"
22		"sync"
23		"sync/atomic"
24		"testing"
25	)
26	
27	// flattenBlocks renders parse results as a deterministic sequence
28	// of "block <keys>" and segment lines for byte-level comparison.
29	func flattenBlocks(blocks []ServerBlock) string {
30		var sb strings.Builder
31		for bi, block := range blocks {
32			sb.WriteString("block ")
33			sb.WriteString(strings.Join(block.GetKeysText(), ","))
34			sb.WriteByte('\n')
35			for _, seg := range block.Segments {
36				for ti, tok := range seg {
37					if ti > 0 {
38						sb.WriteByte(' ')
39					}
40					sb.WriteString(tok.Text)
41				}
42				sb.WriteByte('\n')
43			}
44			if bi < len(blocks)-1 {
45				sb.WriteString("---\n")
46			}
47		}
48		return sb.String()
49	}
50	
51	func mustParseWithReader(t *testing.T, filename string, files map[string]string) string {
52		t.Helper()
53		blocks, err := Parse(filename, []byte(files[filename]), WithImportReader(NewMapImportReader(files)))
54		if err != nil {
55			t.Fatalf("unexpected error: %v", err)
56		}
57		if blocks == nil {
58			t.Fatal("successful parse returned nil blocks")
59		}
60		return flattenBlocks(blocks)
61	}
62	
63	func parseErrWithReader(t *testing.T, filename string, files map[string]string) error {
64		t.Helper()
65		blocks, err := Parse(filename, []byte(files[filename]), WithImportReader(NewMapImportReader(files)))
66		if err == nil {
67			t.Fatalf("expected error, got blocks:\n%s", flattenBlocks(blocks))
68		}
69		if blocks != nil {
70			t.Fatalf("failed parse must not return usable blocks, got:\n%s", flattenBlocks(blocks))
71		}
72		return err
73	}
74	
75	func TestParseWithImportReaderRelativeAndGlobOrder(t *testing.T) {
76		files := map[string]string{
77			"/etc/caddy/Caddyfile": "import sites/*.caddy\n",
78			"/etc/caddy/sites/b.caddy": `b.example.com {
79		respond B
80	}
81	`,
82			"/etc/caddy/sites/a.caddy": `a.example.com {
83		respond A
84	}
85	`,
86			"/etc/caddy/sites/sub/c.caddy": "c.example.com {\n\trespond C\n}\n",
87		}
88		got := mustParseWithReader(t, "/etc/caddy/Caddyfile", files)
89		want := strings.Join([]string{
90			"block a.example.com",
91			"respond A",
92			"---",
93			"block b.example.com",
94			"respond B",
95			"",
96		}, "\n")
97		if got != want {
98			t.Errorf("glob expansion order mismatch\nwant:\n%s\ngot:\n%s", want, got)
99		}
100	}
101	
102	func TestParseWithImportReaderDotSegmentsCleaned(t *testing.T) {
103		files := map[string]string{
104			"/etc/caddy/Caddyfile":     "example.com {\n\timport ./sub/../sites/a.caddy\n}\n",
105			"/etc/caddy/sites/a.caddy": "respond A\n",
106		}
107		got := mustParseWithReader(t, "/etc/caddy/Caddyfile", files)
108		if !strings.Contains(got, "block example.com") || !strings.Contains(got, "respond A") {
109			t.Errorf("relative import with dot segments failed:\n%s", got)
110		}
111	}
112	
113	func TestParseImportErrorsAreFailures(t *testing.T) {
