14	
15	package caddyfile
16	
17	import (
18		"io/fs"
19		"os"
20		"path"
21		"path/filepath"
22		"sort"
23		"time"
24	
25		"github.com/caddyserver/caddy/v2"
26	)
27	
28	// ImportReader abstracts read access to the files reachable from
29	// import directives. A single Parse call reads through one fixed
30	// snapshot of the reader, so swapping the underlying data while a
31	// parse is in flight cannot mix versions into the result.
32	type ImportReader interface {
33		// ReadFile returns the contents of the named file.
34		ReadFile(name string) ([]byte, error)
35	
36		// Stat returns the FileInfo for the named file.
37		Stat(name string) (fs.FileInfo, error)
38	
39		// Glob returns the names of all files matching pattern.
40		Glob(pattern string) ([]string, error)
41	}
42	
43	// ParseOption customizes the behavior of Parse.
44	type ParseOption func(*parseOptions)
45	
46	type parseOptions struct {
47		importReader ImportReader
48	}
49	
50	// WithImportReader resolves import directives against reader instead
51	// of the operating system filesystem. Paths handed to reader are
52	// cleaned absolute paths; relative imports are joined with the
53	// directory of the file that declares them first.
54	func WithImportReader(reader ImportReader) ParseOption {
55		return func(o *parseOptions) {
56			o.importReader = reader
57		}
58	}
59	
60	// osImportReader reads files from the operating system filesystem.
61	// It preserves the historical behavior of Parse.
62	type osImportReader struct{}
63	
64	func (osImportReader) ReadFile(name string) ([]byte, error) { return os.ReadFile(name) }
65	
66	func (osImportReader) Stat(name string) (fs.FileInfo, error) { return os.Stat(name) }
67	
68	func (osImportReader) Glob(pattern string) ([]string, error) { return filepath.Glob(pattern) }
69	
70	// MapImportReader is an in-memory ImportReader backed by a map of
71	// cleaned file paths to their contents. It is safe for ReadFile,
72	// Stat, and Glob to be invoked concurrently on the same reader, as
73	// long as the map is not being mutated at the same time; each Parse
74	// copies anything it reads, so later mutations never affect an
75	// in-flight or completed parse.
76	type MapImportReader struct {
77		files map[string]string
78		dirs  map[string]struct{}
79	}
80	
81	// NewMapImportReader returns a MapImportReader holding files. The
82	// keys are file paths and the values are their contents; parent
83	// directories of every key are synthesized for Stat and Glob.
84	func NewMapImportReader(files map[string]string) *MapImportReader {
85		r := &MapImportReader{
86			files: make(map[string]string, len(files)),
87			dirs:  make(map[string]struct{}),
88		}
89		for name, contents := range files {
90			r.add(filepath.Clean(name), contents)
91		}
92		return r
93	}
94	
95	// Snapshot returns a deep copy of the tree. Parse snapshots its
96	// reader at the very start, so the returned tree is fixed for the
97	// whole call even when the original map is mutated concurrently.
98	func (r *MapImportReader) Snapshot() ImportReader {
99		frozen := &MapImportReader{
100			files: make(map[string]string, len(r.files)),
101			dirs:  make(map[string]struct{}, len(r.dirs)),
102		}
103		for name, contents := range r.files {
104			frozen.files[name] = contents
105		}
106		for d := range r.dirs {
107			frozen.dirs[d] = struct{}{}
108		}
109		return frozen
110	}
111	
112	// add stores a file and records its parent directories.
113	func (r *MapImportReader) add(name, contents string) {
114		r.files[name] = contents
115		for d := filepath.Dir(name); ; d = filepath.Dir(d) {
116			r.dirs[d] = struct{}{}
117			if filepath.Dir(d) == d {
118				break
119			}
120		}
121	}
122	
123	func (r *MapImportReader) ReadFile(name string) ([]byte, error) {
124		if contents, ok := r.files[filepath.Clean(name)]; ok {
125			return []byte(contents), nil
126		}
127		return nil, &fs.PathError{Op: "open", Path: name, Err: fs.ErrNotExist}
128	}
129	
130	func (r *MapImportReader) Stat(name string) (fs.FileInfo, error) {
131		name = filepath.Clean(name)
132		if contents, ok := r.files[name]; ok {
133			return mapFileInfo{name: filepath.Base(name), size: int64(len(contents))}, nil
134		}
135		if _, ok := r.dirs[name]; ok {
136			return mapFileInfo{name: filepath.Base(name), dir: true}, nil
137		}
138		return nil, &fs.PathError{Op: "stat", Path: name, Err: fs.ErrNotExist}
139	}
140	
141	func (r *MapImportReader) Glob(pattern string) ([]string, error) {
142		pattern = filepath.Clean(pattern)
143		var matches []string
144		if _, ok := r.files[pattern]; ok {
145			matches = []string{pattern}
146		} else {
147			for name := range r.files {
148				matched, err := path.Match(filepath.ToSlash(pattern), filepath.ToSlash(name))
149				if err != nil {
150					return nil, err
151				}
152				if matched {
153					matches = append(matches, name)
154				}
155			}
156			sort.Strings(matches)
157		}
158		return matches, nil
159	}
