28	// absKey makes a slash-style absolute path absolute on every
29	// platform, prefixing the temp dir's volume on Windows.
30	func absKey(p string) string {
31		p = filepath.Clean(p)
32		if filepath.IsAbs(p) {
33			return p
34		}
35		if vol := filepath.VolumeName(os.TempDir()); vol != "" {
36			return filepath.Join(vol, p)
37		}
38		return p
39	}
