41	// flattenBlocks renders parse results as a deterministic sequence
42	// of "block <keys>" and segment lines for byte-level comparison.
43	func flattenBlocks(blocks []ServerBlock) string {
44		var sb strings.Builder
45		for bi, block := range blocks {
46			sb.WriteString("block ")
47			sb.WriteString(strings.Join(block.GetKeysText(), ","))
48			sb.WriteByte('\n')
49			for _, seg := range block.Segments {
50				for ti, tok := range seg {
51					if ti > 0 {
52						sb.WriteByte(' ')
53					}
54					sb.WriteString(tok.Text)
55				}
56				sb.WriteByte('\n')
57			}
58			if bi < len(blocks)-1 {
59				sb.WriteString("---\n")
60			}
61		}
62		return sb.String()
63	}
