65	func mustParseWithReader(t *testing.T, filename string, files map[string]string) string {
66		t.Helper()
67		blocks, err := Parse(filename, []byte(files[filename]), WithImportReader(NewMapImportReader(files)))
68		if err != nil {
69			t.Fatalf("unexpected error: %v", err)
70		}
71		if blocks == nil {
72			t.Fatal("successful parse returned nil blocks")
73		}
74		return flattenBlocks(blocks)
75	}
