77	func parseErrWithReader(t *testing.T, filename string, files map[string]string) error {
78		t.Helper()
79		blocks, err := Parse(filename, []byte(files[filename]), WithImportReader(NewMapImportReader(files)))
80		if err == nil {
81			t.Fatalf("expected error, got blocks:\n%s", flattenBlocks(blocks))
82		}
83		if blocks != nil {
84			t.Fatalf("failed parse must not return usable blocks, got:\n%s", flattenBlocks(blocks))
85		}
86		return err
