194	// versionedReader returns a different suffix on every ReadFile,
195	// simulating a reader that serves another version on repeat reads.
196	type versionedReader struct {
197		mu       sync.Mutex
198		contents map[string]string
199		reads    map[string]int
200	}
201	
202	func (r *versionedReader) ReadFile(name string) ([]byte, error) {
203		r.mu.Lock()
204		defer r.mu.Unlock()
205		body, ok := r.contents[name]
206		if !ok {
207			return nil, &fs.PathError{Op: "open", Path: name, Err: fs.ErrNotExist}
208		}
209		r.reads[name]++
210		return []byte(strings.Replace(body, "VERSION", "read"+itoa(r.reads[name]), 1)), nil
211	}
212	func (r *versionedReader) Stat(name string) (fs.FileInfo, error) {
213		r.mu.Lock()
214		defer r.mu.Unlock()
215		body, ok := r.contents[name]
216		if !ok {
217			return nil, &fs.PathError{Op: "stat", Path: name, Err: fs.ErrNotExist}
218		}
219		return mapFileInfo{name: filepath.Base(name), size: int64(len(body))}, nil
220	}
221	func (r *versionedReader) Glob(pattern string) ([]string, error) {
222		r.mu.Lock()
223		defer r.mu.Unlock()
224		var out []string
225		for name := range r.contents {
226			matched, err := filepath.Match(pattern, name)
227			if err != nil {
228				return nil, err
229			}
230			if matched {
231				out = append(out, name)
232			}
233		}
234		sortStrings(out)
235		return out, nil
236	}
